func contractFor(method, path string) operationContract {
	for _, c := range operationContracts {
		if c.method == method && c.pattern.MatchString(path) {
			return c
		}
	}
	return operationContract{apiKey: true, apiKeyStore: true, apiKeyUsesStore: true}
}

const maxRetryDelay = 30 * time.Second

type multipartRequestBody struct{ value any }
type RawResponse[T any] struct {
	Data       T
	StatusCode int
	Headers    http.Header
	RequestID  string
	RawBody    []byte
}
type responseMetadata struct {
	status    int
	headers   http.Header
	requestID string
	rawBody   []byte
}

func withResponseMetadata(target **responseMetadata) RequestOption {
	return withResponseCapture(func(resp *http.Response, raw []byte) {
		*target = &responseMetadata{status: resp.StatusCode, headers: resp.Header.Clone(), requestID: resp.Header.Get("X-Request-ID"), rawBody: append([]byte(nil), raw...)}
	})
}
func rawResponse[T any](data T, meta *responseMetadata) *RawResponse[T] {
	if meta == nil {
		return &RawResponse[T]{Data: data}
	}
	return &RawResponse[T]{Data: data, StatusCode: meta.status, Headers: meta.headers, RequestID: meta.requestID, RawBody: meta.rawBody}
}

type CustomRequest struct {
	Method string
	Path   string
	Query  url.Values
	Body   any
}

func multipartBody(value any) any { return multipartRequestBody{value: value} }
func (c *Client) Request(ctx context.Context, request CustomRequest, opts ...RequestOption) (*RawResponse[json.RawMessage], error) {
	method := strings.ToUpper(strings.TrimSpace(request.Method))
	if matched, _ := regexp.MatchString("^[A-Z]+$", method); !matched {
		return nil, &ConfigurationError{Err: fmt.Errorf("invalid HTTP method")}
	}
	var value json.RawMessage
	var captured *RawResponse[json.RawMessage]
	opts = append(opts, withOperation("custom", false), withResponseCapture(func(resp *http.Response, raw []byte) {
		captured = &RawResponse[json.RawMessage]{Data: append(json.RawMessage(nil), value...), StatusCode: resp.StatusCode, Headers: resp.Header.Clone(), RequestID: resp.Header.Get("X-Request-ID"), RawBody: append([]byte(nil), raw...)}
	}))
	_, err := c.request(ctx, method, request.Path, request.Query, request.Body, &value, opts)
	if err != nil {
		return nil, err
	}
	return captured, nil
}
func (c *Client) buildURL(path string, query any, _ []RequestOption) string {
	u, _ := url.Parse(strings.TrimRight(c.baseURL, "/") + "/" + strings.TrimLeft(path, "/"))
	u.RawQuery = encodeQuery(query).Encode()
	return u.String()
}
func (c *Client) request(ctx context.Context, method, path string, query, body, result any, opts []RequestOption) (*http.Response, error) {
	if c.configErr != nil {
		return nil, &ConfigurationError{Err: c.configErr}
	}
	cfg := requestConfig{headers: make(http.Header), maxRetries: c.maxRetries}
	for _, opt := range opts {
		opt(&cfg)
	}
	if cfg.maxRetries < 0 {
		return nil, &ConfigurationError{Err: fmt.Errorf("max retries must be non-negative")}
	}
	if cfg.timeoutSet && cfg.timeout <= 0 {
		return nil, &ConfigurationError{Err: fmt.Errorf("request timeout must be positive")}
	}
	if key := cfg.headers.Get("Idempotency-Key"); strings.TrimSpace(key) != "" && !cfg.idempotencySupported {
		return nil, &ConfigurationError{Err: fmt.Errorf("operation does not declare Idempotency-Key support")}
	}
	contract := contractFor(method, path)
	session := cfg.customerSession
	if session == "" {
		session = c.customerSession
	}
	authorization := ""
	store := ""
	sessionUsed := false
	switch {
	case contract.customerSession && session != "":
		authorization = "Bearer " + session
		sessionUsed = true
	case contract.accessToken && c.accessToken != "":
		if contract.accessTokenStore && c.store == "" {
			return nil, &ConfigurationError{Err: fmt.Errorf("store is required for OAuth access tokens")}
		}
		authorization = "Bearer " + c.accessToken
		if contract.accessTokenStore {
			store = c.store
		}
	case contract.apiKey && c.apiKey != "":
		if contract.apiKeyStore && c.store == "" {
			return nil, &ConfigurationError{Err: fmt.Errorf("store is required")}
		}
		authorization = "Bearer " + c.apiKey
		if contract.apiKeyUsesStore {
			store = c.store
		}
	case contract.browserSession && c.browserSession != "":
	case contract.clientBasic && c.clientID != "":
		authorization = "Basic " + base64.StdEncoding.EncodeToString([]byte(url.QueryEscape(c.clientID)+":"+url.QueryEscape(c.clientSecret)))
	case contract.anonymous:
	default:
		return nil, &AuthenticationError{APIError: APIError{Type: "authentication_error", Message: "credentials required by this operation are missing", Status: 401}}
	}
	if err := validateRelativePath(path); err != nil {
		return nil, &ConfigurationError{Err: err}
	}
	payload, contentType, err := encodeRequestBody(body)
	if err != nil {
		return nil, &SerializationError{Err: err}
	}
	if contract.form && body != nil {
		var fields map[string]any
		if err := json.Unmarshal(payload, &fields); err != nil {
			return nil, &SerializationError{Err: err}
		}
		if contract.clientBasic && c.clientID != "" {
			if _, ok := fields["client_id"]; ok {
				return nil, &ConfigurationError{Err: fmt.Errorf("use Basic or body credentials, never both")}
			}
			if _, ok := fields["client_secret"]; ok {
				return nil, &ConfigurationError{Err: fmt.Errorf("use Basic or body credentials, never both")}
			}
		}
		form := url.Values{}
		for k, v := range fields {
			if values, ok := v.([]any); ok {
				for _, item := range values {
					form.Add(k+"[]", fmt.Sprint(item))
				}
			} else if v != nil {
				form.Set(k, fmt.Sprint(v))
			}
		}
		payload = []byte(form.Encode())
		contentType = "application/x-www-form-urlencoded"
	}
	endpoint := c.buildURL(path, query, nil)
	if contract.server != "" {
		base := contract.server
		if c.baseURL != defaultBaseURL {
			u, _ := url.Parse(c.baseURL)
			base = u.Scheme + "://" + u.Host
		}
		endpoint = strings.TrimRight(base, "/") + "/" + strings.TrimLeft(path, "/")
		if q := encodeQuery(query).Encode(); q != "" {
			endpoint += "?" + q
		}
	}
	retryable := !sessionUsed && !contract.neverRetry && (isRetryableMethod(method) || contract.declaredIdempotency && cfg.idempotencySupported && strings.TrimSpace(cfg.headers.Get("Idempotency-Key")) != "")
	for attempt := 0; ; attempt++ {
		attemptCtx := ctx
		cancel := func() {}
		if cfg.timeout > 0 {
			attemptCtx, cancel = context.WithTimeout(ctx, cfg.timeout)
		}
		started := time.Now()
		req, err := http.NewRequestWithContext(attemptCtx, method, endpoint, bytes.NewReader(payload))
		if err != nil {
			cancel()
			return nil, &TransportError{Err: err}
		}
		req.Header.Set("User-Agent", "SellApp Go/0.1.1")
		if contentType != "" {
			req.Header.Set("Content-Type", contentType)
		}
		for k, vs := range cfg.headers {
			for _, v := range vs {
				req.Header.Add(k, v)
			}
		}
		req.Header.Del("Authorization")
		req.Header.Del("X-STORE")
		req.Header.Del("Cookie")
		if authorization != "" {
			req.Header.Set("Authorization", authorization)
		}
		if store != "" {
			req.Header.Set("X-STORE", store)
		}
		if contract.browserSession && c.browserSession != "" {
			req.Header.Set("Cookie", c.browserSession)
		}
		transport := *c.httpClient
		transport.CheckRedirect = func(_ *http.Request, _ []*http.Request) error { return http.ErrUseLastResponse }
		resp, err := transport.Do(req)
		if c.hook != nil {
			event := RequestEvent{OperationID: cfg.operationID, Attempt: attempt + 1, Duration: time.Since(started), Err: err}
			if resp != nil {
				event.Status = resp.StatusCode
				event.RequestID = resp.Header.Get("X-Request-ID")
			}
			c.hook(event)
		}
		if err != nil {
			cancel()
			if !retryable || attempt >= cfg.maxRetries {
				return nil, classifyTransportError(err)
			}
			if err := sleepContext(ctx, retryDelay(nil, attempt, time.Now())); err != nil {
				return nil, classifyTransportError(err)
			}
			continue
		}
		if (resp.StatusCode == 408 || resp.StatusCode == 409 || resp.StatusCode == 429 || resp.StatusCode >= 500) && retryable && attempt < cfg.maxRetries {
			delay := retryDelay(resp, attempt, time.Now())
			_ = resp.Body.Close()
			cancel()
			if err := sleepContext(ctx, delay); err != nil {
				return nil, classifyTransportError(err)
			}
			continue
		}
		if resp.StatusCode < 200 || resp.StatusCode >= 400 {
			defer cancel()
			return resp, decodeAPIError(resp)
		}
		defer cancel()
		defer resp.Body.Close()
		raw, err := io.ReadAll(resp.Body)
		if err != nil {
			return resp, &TransportError{Err: err}
		}
		if result != nil && len(raw) > 0 && resp.StatusCode < 300 {
			if contract.textResponse {
				if text, ok := result.(*string); ok {
					*text = string(raw)
				} else if err := json.Unmarshal(raw, result); err != nil {
					return resp, &SerializationError{Err: err}
				}
			} else if err := json.Unmarshal(raw, result); err != nil {
				return resp, &SerializationError{Err: err}
			}
		}
		if cfg.capture != nil {
			cfg.capture(resp, raw)
		}
		return resp, nil
	}
}
func encodeRequestBody(body any) ([]byte, string, error) {
	if body == nil {
		return nil, "", nil
	}
	if validated, ok := body.(validatedRequestBody); ok {
		candidate := validated.value
		if multipart, ok := candidate.(multipartRequestBody); ok {
			candidate = multipart.value
		}
		payload, err := json.Marshal(candidate)
		if err != nil {
			return nil, "", err
		}
		if err := validateRuntimeJSON(payload, validated.schema, requestSchemaValidation); err != nil {
			return nil, "", err
		}
		body = validated.value
	}
	if value, ok := body.(multipartRequestBody); ok {
		payload, contentType, err := encodeMultipartBody(value.value)
		return payload, contentType, err
	}
	payload, err := json.Marshal(body)
	return payload, "application/json", err
}
func encodeMultipartBody(body any) ([]byte, string, error) {
	var payload bytes.Buffer
	writer := multipart.NewWriter(&payload)
	if err := writeMultipartFields(writer, body); err != nil {
		_ = writer.Close()
		return nil, "", err
	}
	if err := writer.Close(); err != nil {
		return nil, "", err
	}
	return payload.Bytes(), writer.FormDataContentType(), nil
}
func writeMultipartFields(writer *multipart.Writer, body any) error {
	value := reflect.ValueOf(body)
	for value.IsValid() && (value.Kind() == reflect.Pointer || value.Kind() == reflect.Interface) {
		if value.IsNil() {
			return nil
		}
		value = value.Elem()
	}
	if !value.IsValid() || value.Kind() != reflect.Struct {
		return fmt.Errorf("multipart body must be a struct, got %T", body)
	}
	typ := value.Type()
	for index := 0; index < value.NumField(); index++ {
		fieldInfo := typ.Field(index)
		if fieldInfo.PkgPath != "" {
			continue
		}
		tag := strings.Split(fieldInfo.Tag.Get("json"), ",")
		name := tag[0]
		if name == "" {
			name = fieldInfo.Name
		}
		if name == "-" {
			continue
		}
		omitEmpty := false
		for _, option := range tag[1:] {
			if option == "omitempty" {
				omitEmpty = true
			}
		}
		field := value.Field(index)
		if omitEmpty && field.IsZero() {
			continue
		}
		if err := writeMultipartField(writer, name, field); err != nil {
			return fmt.Errorf("multipart field %s: %w", name, err)
		}
	}
	return nil
}
func writeMultipartField(writer *multipart.Writer, name string, value reflect.Value) error {
	for value.IsValid() && (value.Kind() == reflect.Pointer || value.Kind() == reflect.Interface) {
		if value.IsNil() {
			return nil
		}
		value = value.Elem()
	}
	if !value.IsValid() {
		return nil
	}
	if value.Kind() == reflect.Slice && value.Type().Elem().Kind() == reflect.Uint8 {
		part, err := writer.CreateFormFile(name, name)
		if err != nil {
			return err
		}
		_, err = part.Write(value.Bytes())
		return err
	}
	if value.Kind() == reflect.Slice || value.Kind() == reflect.Array {
		for index := 0; index < value.Len(); index++ {
			if err := writeMultipartField(writer, name, value.Index(index)); err != nil {
				return err
			}
		}
		return nil
	}
	switch value.Kind() {
	case reflect.String:
		return writer.WriteField(name, value.String())
	case reflect.Bool:
		return writer.WriteField(name, strconv.FormatBool(value.Bool()))
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return writer.WriteField(name, strconv.FormatInt(value.Int(), 10))
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return writer.WriteField(name, strconv.FormatUint(value.Uint(), 10))
	case reflect.Float32, reflect.Float64:
		return writer.WriteField(name, strconv.FormatFloat(value.Float(), 'g', -1, value.Type().Bits()))
	}
	encoded, err := json.Marshal(value.Interface())
	if err != nil {
		return err
	}
	return writer.WriteField(name, string(encoded))
}
func validateRelativePath(path string) error {
	u, err := url.Parse(path)
	if err != nil || strings.TrimSpace(path) == "" || u.IsAbs() || u.Host != "" || u.User != nil || u.Fragment != "" || u.Opaque != "" || strings.HasPrefix(path, "//") {
		return fmt.Errorf("request path must be relative and contain no authority, credentials, or fragment")
	}
	return nil
}
func isRetryableMethod(method string) bool {
	switch strings.ToUpper(method) {
	case http.MethodGet, http.MethodHead, http.MethodOptions, http.MethodTrace, http.MethodPut, http.MethodDelete:
		return true
	default:
		return false
	}
}
func classifyTransportError(err error) error {
	if errors.Is(err, context.Canceled) {
		return &CancellationError{Err: err}
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return &TimeoutError{Err: err}
	}
	return &TransportError{Err: err}
}
func retryDelay(resp *http.Response, attempt int, now time.Time) time.Duration {
	if resp != nil {
		if delay, ok := parseRetryAfter(resp.Header.Get("Retry-After"), now); ok {
			return clampRetryDelay(delay)
		}
	}
	if attempt < 0 {
		attempt = 0
	}
	if attempt > 8 {
		attempt = 8
	}
	base := time.Duration(1<<attempt) * 100 * time.Millisecond
	return clampRetryDelay(base + time.Duration(rand.Int63n(int64(base)+1)))
}
func parseRetryAfter(value string, now time.Time) (time.Duration, bool) {
	value = strings.TrimSpace(value)
	if value == "" {
		return 0, false
	}
	digits := true
	for _, character := range value {
		if character < '0' || character > '9' {
			digits = false
			break
		}
	}
	if digits {
		seconds, err := strconv.ParseUint(value, 10, 64)
		if err != nil || seconds > uint64(maxRetryDelay/time.Second) {
			return maxRetryDelay, true
		}
		return time.Duration(seconds) * time.Second, true
	}
	when, err := http.ParseTime(value)
	if err != nil {
		return 0, false
	}
	delay := when.Sub(now)
	if delay < 0 {
		delay = 0
	}
	return delay, true
}
func clampRetryDelay(delay time.Duration) time.Duration {
	if delay < 0 {
		return 0
	}
	if delay > maxRetryDelay {
		return maxRetryDelay
	}
	return delay
}
func sleepContext(ctx context.Context, delay time.Duration) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if delay <= 0 {
		return nil
	}
	timer := time.NewTimer(delay)
	defer timer.Stop()
	select {
	case <-timer.C:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}
func encodeQuery(value any) url.Values {
	out := url.Values{}
	if value == nil {
		return out
	}
	if v, ok := value.(url.Values); ok {
		return v
	}
	rv := reflect.ValueOf(value)
	for rv.IsValid() && (rv.Kind() == reflect.Pointer || rv.Kind() == reflect.Interface) {
		if rv.IsNil() {
			return out
		}
		rv = rv.Elem()
	}
	if !rv.IsValid() || rv.Kind() != reflect.Struct {
		return out
	}
	rt := rv.Type()
	for index := 0; index < rv.NumField(); index++ {
		field := rt.Field(index)
		tag := field.Tag.Get("url")
		name := strings.Split(tag, ",")[0]
		if name == "" || name == "-" {
			continue
		}
		item := rv.Field(index)
		for item.IsValid() && (item.Kind() == reflect.Pointer || item.Kind() == reflect.Interface) {
			if item.IsNil() {
				item = reflect.Value{}
				break
			}
			item = item.Elem()
		}
		if !item.IsValid() {
			continue
		}
		if item.Kind() == reflect.Slice || item.Kind() == reflect.Array {
			for element := 0; element < item.Len(); element++ {
				out.Add(name, fmt.Sprint(item.Index(element).Interface()))
			}
		} else {
			out.Set(name, fmt.Sprint(item.Interface()))
		}
	}
	return out
}

type schemaConstraints struct {
	Minimum          *float64
	Maximum          *float64
	ExclusiveMinimum any
	ExclusiveMaximum any
	MultipleOf       *float64
	MinLength        *int
	MaxLength        *int
	Pattern          string
	MinItems         *int
	MaxItems         *int
	UniqueItems      bool
	MinProperties    *int
	MaxProperties    *int
}
type runtimeDiscriminator struct {
	Property string
	Values   []string
	Mapping  map[string]runtimeSchema
}
type runtimeSchema struct {
	Kind                 string
	ModelName            string
	Type                 string
	Format               string
	Constraints          *schemaConstraints
	Items                *runtimeSchema
	Values               []any
	Value                any
	Inner                *runtimeSchema
	Properties           map[string]runtimeSchema
	Required             []string
	AdditionalProperties any
	Variants             []runtimeSchema
	Composition          string
	Discriminator        *runtimeDiscriminator
}
type schemaValidationOptions struct {
	direction                                                        string
	allowUnknownEnums, allowUnknownUnionVariants, allowUnknownFields bool
	models                                                           map[string]runtimeSchema
}

var requestSchemaValidation = schemaValidationOptions{direction: "request"}
var responseSchemaValidation = schemaValidationOptions{direction: "response", allowUnknownEnums: true, allowUnknownUnionVariants: true, allowUnknownFields: true}

// SchemaValidationError reports a request or response value that violates the OpenAPI contract.
type SchemaValidationError struct{ Direction, Path, Problem string }

func (e *SchemaValidationError) Error() string {
	return fmt.Sprintf("invalid %s schema at %s: %s", e.Direction, e.Path, e.Problem)
}

func mustRuntimeSchema(encoded string) runtimeSchema {
	var schema runtimeSchema
	if err := json.Unmarshal([]byte(encoded), &schema); err != nil {
		panic(err)
	}
	return schema
}
func validateRuntimeJSON(data []byte, schema runtimeSchema, options schemaValidationOptions) error {
	var value any
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.UseNumber()
	if err := decoder.Decode(&value); err != nil {
		return err
	}
	return validateRuntimeValue(value, schema, "$", options)
}
func validateRuntimeValue(value any, schema runtimeSchema, path string, options schemaValidationOptions) error {
	if options.models == nil {
		options.models = map[string]runtimeSchema{}
	}
	if schema.Kind == "ref" {
		referenced, ok := options.models[schema.ModelName]
		if !ok {
			return runtimeValidationError(options, path, "has an unresolved model schema")
		}
		return validateRuntimeValue(value, referenced, path, options)
	}
	if schema.ModelName != "" {
		options.models[schema.ModelName] = schema
	}
	if schema.Kind == "any" {
		return nil
	}
	if schema.Kind == "nullable" {
		if value == nil {
			return nil
		}
		return validateRuntimeValue(value, *schema.Inner, path, options)
	}
	if schema.Kind == "literal" {
		if !runtimeEqual(value, schema.Value) {
			return runtimeValidationError(options, path, "must equal "+fmt.Sprint(schema.Value))
		}
		return nil
	}
	if schema.Kind == "enum" {
		for _, candidate := range schema.Values {
			if runtimeEqual(value, candidate) {
				return nil
			}
		}
		sameType := false
		for _, candidate := range schema.Values {
			switch candidate.(type) {
			case string:
				_, sameType = value.(string)
			case float64:
				_, sameType = runtimeNumber(value)
			case bool:
				_, sameType = value.(bool)
			}
			if sameType {
				break
			}
		}
		if options.direction == "response" && options.allowUnknownEnums && sameType {
			return nil
		}
		return runtimeValidationError(options, path, "must be one of the declared enum values")
	}
	if schema.Kind == "primitive" {
		return validateRuntimePrimitive(value, schema, path, options)
	}
	if schema.Kind == "array" {
		values, ok := value.([]any)
		if !ok {
			return runtimeValidationError(options, path, "must be an array")
		}
		if err := validateRuntimeCollectionConstraints(len(values), schema.Constraints, path, options, false); err != nil {
			return err
		}
		if schema.Constraints != nil && schema.Constraints.UniqueItems {
			seen := map[string]struct{}{}
			for _, item := range values {
				encoded, _ := json.Marshal(item)
				key := string(encoded)
				if _, ok := seen[key]; ok {
					return runtimeValidationError(options, path, "must contain unique items")
				}
				seen[key] = struct{}{}
			}
		}
		for index, item := range values {
			if err := validateRuntimeValue(item, *schema.Items, fmt.Sprintf("%s[%d]", path, index), options); err != nil {
				return err
			}
		}
		return nil
	}
	if schema.Kind == "map" {
		object, ok := value.(map[string]any)
		if !ok {
			return runtimeValidationError(options, path, "must be an object")
		}
		if err := validateRuntimeCollectionConstraints(len(object), schema.Constraints, path, options, true); err != nil {
			return err
		}
		for key, item := range object {
			if err := validateRuntimeValue(item, *schema.Items, path+"."+key, options); err != nil {
				return err
			}
		}
		return nil
	}
	if schema.Kind == "object" {
		object, ok := value.(map[string]any)
		if !ok {
			return runtimeValidationError(options, path, "must be an object")
		}
		if err := validateRuntimeCollectionConstraints(len(object), schema.Constraints, path, options, true); err != nil {
			return err
		}
		for _, key := range schema.Required {
			if _, exists := object[key]; !exists {
				return runtimeValidationError(options, path+"."+key, "is required")
			}
		}
		for key, item := range object {
			property, known := schema.Properties[key]
			if known {
				if err := validateRuntimeValue(item, property, path+"."+key, options); err != nil {
					return err
				}
				continue
			}
			switch additional := schema.AdditionalProperties.(type) {
			case bool:
				if !additional && !options.allowUnknownFields {
					return runtimeValidationError(options, path+"."+key, "is not allowed")
				}
			case map[string]any:
				encoded, _ := json.Marshal(additional)
				var nested runtimeSchema
				if json.Unmarshal(encoded, &nested) == nil {
					if err := validateRuntimeValue(item, nested, path+"."+key, options); err != nil {
						return err
					}
				}
			}
		}
		return nil
	}
	if schema.Kind == "union" {
		if schema.Discriminator != nil {
			object, ok := value.(map[string]any)
			if !ok {
				return runtimeValidationError(options, path, "must be an object")
			}
			tag, ok := object[schema.Discriminator.Property].(string)
			if !ok {
				return runtimeValidationError(options, path+"."+schema.Discriminator.Property, "must be a string discriminator")
			}
			if variant, known := schema.Discriminator.Mapping[tag]; known {
				return validateRuntimeValue(value, variant, path, options)
			}
			for _, candidate := range schema.Discriminator.Values {
				if tag == candidate {
					return nil
				}
			}
			if options.direction == "response" && options.allowUnknownUnionVariants {
				return nil
			}
			return runtimeValidationError(options, path+"."+schema.Discriminator.Property, "has unknown union variant "+tag)
		}
		matches := 0
		for _, variant := range schema.Variants {
			if validateRuntimeValue(value, variant, path, options) == nil {
				matches++
			}
		}
		if schema.Composition == "oneOf" && matches != 1 || schema.Composition == "allOf" && matches != len(schema.Variants) || schema.Composition != "oneOf" && schema.Composition != "allOf" && matches < 1 {
			return runtimeValidationError(options, path, "does not match the union schema")
		}
		return nil
	}
	return nil
}
func validateRuntimePrimitive(value any, schema runtimeSchema, path string, options schemaValidationOptions) error {
	switch schema.Type {
	case "string":
		text, ok := value.(string)
		if !ok {
			return runtimeValidationError(options, path, "must be a string")
		}
		if schema.Constraints != nil {
			length := utf8.RuneCountInString(text)
			if schema.Constraints.MinLength != nil && length < *schema.Constraints.MinLength {
				return runtimeValidationError(options, path, "is shorter than minLength")
			}
			if schema.Constraints.MaxLength != nil && length > *schema.Constraints.MaxLength {
				return runtimeValidationError(options, path, "is longer than maxLength")
			}
			if schema.Constraints.Pattern != "" {
				matched, err := regexp.MatchString(schema.Constraints.Pattern, text)
				if err != nil || !matched {
					return runtimeValidationError(options, path, "does not match the required pattern")
				}
			}
		}
	case "boolean":
		if _, ok := value.(bool); !ok {
			return runtimeValidationError(options, path, "must be a boolean")
		}
	case "integer", "number":
		number, ok := runtimeNumber(value)
		if !ok {
			return runtimeValidationError(options, path, "must be a number")
		}
		if schema.Type == "integer" && math.Trunc(number) != number {
			return runtimeValidationError(options, path, "must be an integer")
		}
		if err := validateRuntimeNumberConstraints(number, schema.Constraints, path, options); err != nil {
			return err
		}
	}
	return nil
}
func validateRuntimeNumberConstraints(value float64, c *schemaConstraints, path string, options schemaValidationOptions) error {
	if c == nil {
		return nil
	}
	if c.Minimum != nil && value < *c.Minimum {
		return runtimeValidationError(options, path, "is below minimum")
	}
	if c.Maximum != nil && value > *c.Maximum {
		return runtimeValidationError(options, path, "is above maximum")
	}
	if bound, ok := runtimeNumber(c.ExclusiveMinimum); ok && value <= bound {
		return runtimeValidationError(options, path, "is not above exclusiveMinimum")
	}
	if flag, ok := c.ExclusiveMinimum.(bool); ok && flag && c.Minimum != nil && value <= *c.Minimum {
		return runtimeValidationError(options, path, "is not above exclusiveMinimum")
	}
	if bound, ok := runtimeNumber(c.ExclusiveMaximum); ok && value >= bound {
		return runtimeValidationError(options, path, "is not below exclusiveMaximum")
	}
	if flag, ok := c.ExclusiveMaximum.(bool); ok && flag && c.Maximum != nil && value >= *c.Maximum {
		return runtimeValidationError(options, path, "is not below exclusiveMaximum")
	}
	if c.MultipleOf != nil && math.Abs(value / *c.MultipleOf - math.Round(value / *c.MultipleOf)) > 1e-10 {
		return runtimeValidationError(options, path, "is not a multipleOf value")
	}
	return nil
}
func validateRuntimeCollectionConstraints(length int, c *schemaConstraints, path string, options schemaValidationOptions, object bool) error {
	if c == nil {
		return nil
	}
	minimum, maximum := c.MinItems, c.MaxItems
	if object {
		minimum, maximum = c.MinProperties, c.MaxProperties
	}
	if minimum != nil && length < *minimum {
		return runtimeValidationError(options, path, "contains too few values")
	}
	if maximum != nil && length > *maximum {
		return runtimeValidationError(options, path, "contains too many values")
	}
	return nil
}
func runtimeNumber(value any) (float64, bool) {
	switch number := value.(type) {
	case json.Number:
		v, err := number.Float64()
		return v, err == nil
	case float64:
		return number, true
	case float32:
		return float64(number), true
	case int:
		return float64(number), true
	case int64:
		return float64(number), true
	default:
		return 0, false
	}
}
func runtimeEqual(left, right any) bool {
	if l, ok := runtimeNumber(left); ok {
		if r, ok := runtimeNumber(right); ok {
			return l == r
		}
	}
	return reflect.DeepEqual(left, right)
}
func runtimeValidationError(options schemaValidationOptions, path, problem string) error {
	return &SchemaValidationError{Direction: options.direction, Path: path, Problem: problem}
}
func preserveUnknownJSON(raw map[string]json.RawMessage, knownKeys []string) map[string]json.RawMessage {
	known := map[string]struct{}{}
	for _, key := range knownKeys {
		known[key] = struct{}{}
	}
	unknown := map[string]json.RawMessage{}
	for key, value := range raw {
		if _, ok := known[key]; !ok {
			unknown[key] = append(json.RawMessage(nil), value...)
		}
	}
	if len(unknown) == 0 {
		return nil
	}
	return unknown
}
func mergeUnknownJSON(data []byte, unknown map[string]json.RawMessage) ([]byte, error) {
	if len(unknown) == 0 {
		return data, nil
	}
	raw := map[string]json.RawMessage{}
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, err
	}
	for key, value := range unknown {
		if _, known := raw[key]; !known {
			raw[key] = value
		}
	}
	return json.Marshal(raw)
}

type validatedRequestBody struct {
	value  any
	schema runtimeSchema
}

func schemaValidatedBody(value any, schema runtimeSchema) any {
	return validatedRequestBody{value: value, schema: schema}
}
